import Foundation

/// Parses raw responses from Apple Foundation Models into structured `AgentMessage`s for the billing harness.
public struct LLMResponseParser {
    /// Parses the raw string generated by the AI into an `AgentMessage`.
    public static func parse(
        content: String,
        catalog: [Item],
        settings: AppSettings
    ) -> AgentMessage {
        var cleanContent = content
            .replacingOccurrences(of: "<start_of_turn>model", with: "")
            .replacingOccurrences(of: "<start_of_turn>", with: "")
            .replacingOccurrences(of: "<end_of_turn>", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)

        var thought: String? = nil

        // 1. Extract thought process enclosed in <thought> or <thinking> tags
        if let thoughtStart = cleanContent.range(of: "<thought>"),
           let thoughtEnd = cleanContent.range(of: "</thought>") {
            let thoughtSubstr = cleanContent[thoughtStart.upperBound..<thoughtEnd.lowerBound]
            thought = String(thoughtSubstr).trimmingCharacters(in: .whitespacesAndNewlines)
            cleanContent.removeSubrange(thoughtStart.lowerBound..<thoughtEnd.upperBound)
        } else if let thoughtStart = cleanContent.range(of: "<thinking>"),
                  let thoughtEnd = cleanContent.range(of: "</thinking>") {
            let thoughtSubstr = cleanContent[thoughtStart.upperBound..<thoughtEnd.lowerBound]
            thought = String(thoughtSubstr).trimmingCharacters(in: .whitespacesAndNewlines)
            cleanContent.removeSubrange(thoughtStart.lowerBound..<thoughtEnd.upperBound)
        }

        // 2. Extract structured JSON payload
        var extractedJson: String? = nil
        var parsedPayload: AgentJsonPayload? = nil

        let jsonCandidates = extractJsonCandidates(from: cleanContent)
        for candidate in jsonCandidates {
            if let payload = decodePayload(from: candidate) {
                extractedJson = candidate
                parsedPayload = payload
                break
            }
        }

        // 3. Fallback: If no structured items were parsed from JSON, attempt catalog matching from text
        if parsedPayload?.items == nil || parsedPayload?.items?.isEmpty == true {
            let fallbackItems = extractFallbackItems(from: cleanContent, catalog: catalog)
            if !fallbackItems.isEmpty {
                if parsedPayload != nil {
                    parsedPayload?.items = fallbackItems
                } else {
                    parsedPayload = AgentJsonPayload(
                        status: "ready",
                        message: "Items identified from catalog.",
                        items: fallbackItems
                    )
                }
            }
        }

        // 4. Compute financial bill summary from parsed items
        var billSummary: BillSummary? = nil
        if let items = parsedPayload?.items, !items.isEmpty {
            billSummary = BillCalculator.computeBill(
                from: items,
                catalog: catalog,
                currencySymbol: settings.currencySymbol,
                taxRatePercent: settings.taxRatePercent
            )
        }

        // 5. Extract user-facing message
        let displayText: String = {
            if let payload = parsedPayload, !payload.message.isEmpty {
                return payload.message
            }
            if let items = parsedPayload?.items, !items.isEmpty {
                let itemDesc = items.map { "\($0.quantity)\($0.unit.isEmpty ? "" : " " + $0.unit) \($0.itemName)" }.joined(separator: ", ")
                return "Added \(itemDesc) to the bill."
            }
            var text = cleanContent
            if let json = extractedJson {
                text = text.replacingOccurrences(of: "```json\n\(json)\n```", with: "")
                text = text.replacingOccurrences(of: "```\(json)```", with: "")
                text = text.replacingOccurrences(of: json, with: "")
            }
            let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? "Order processed." : trimmed
        }()

        let status: AgentResponseStatus = (parsedPayload?.status == "needs_clarification") ? .needsClarification : .ready
        let hasAutoCorrection = parsedPayload?.items?.contains { $0.wasAutoCorrected == true } == true

        return AgentMessage(
            role: .agent,
            text: displayText,
            thoughtProcess: thought ?? parsedPayload?.thought,
            rawJsonOutput: extractedJson,
            status: status,
            billSummary: billSummary,
            parsedItems: parsedPayload?.items,
            pendingClarification: parsedPayload?.pendingClarification,
            hasAutoCorrection: hasAutoCorrection,
            unitCorrectionNotes: parsedPayload?.unitCorrections,
            canUndo: true
        )
    }

    private static func extractJsonCandidates(from text: String) -> [String] {
        var candidates: [String] = []

        // Pattern 1: Content inside ```json ... ``` or ``` ... ```
        let fencePattern = #"```(?:json)?\s*([\s\S]*?)\s*```"#
        if let regex = try? NSRegularExpression(pattern: fencePattern, options: []) {
            let nsText = text as NSString
            let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: text.utf16.count))
            for match in matches {
                if match.numberOfRanges > 1 {
                    let range = match.range(at: 1)
                    let sub = nsText.substring(with: range).trimmingCharacters(in: .whitespacesAndNewlines)
                    if !sub.isEmpty {
                        candidates.append(sub)
                    }
                }
            }
        }

        // Pattern 2: Widest {...} object in text
        if let openBrace = text.firstIndex(of: "{"),
           let closeBrace = text.lastIndex(of: "}"),
           openBrace < closeBrace {
            let candidate = String(text[openBrace...closeBrace])
            if !candidates.contains(candidate) {
                candidates.append(candidate)
            }
        }

        // Pattern 3: Widest [...] array in text
        if let openBracket = text.firstIndex(of: "["),
           let closeBracket = text.lastIndex(of: "]"),
           openBracket < closeBracket {
            let candidate = String(text[openBracket...closeBracket])
            if !candidates.contains(candidate) {
                candidates.append(candidate)
            }
        }

        return candidates
    }

    private static func decodePayload(from jsonStr: String) -> AgentJsonPayload? {
        guard let data = jsonStr.data(using: .utf8) else { return nil }

        // 1. Try decoding standard AgentJsonPayload
        if let payload = try? JSONDecoder().decode(AgentJsonPayload.self, from: data) {
            return payload
        }

        // 2. Try decoding as direct [AgentParsedItem] array
        if let items = try? JSONDecoder().decode([AgentParsedItem].self, from: data), !items.isEmpty {
            return AgentJsonPayload(
                status: "ready",
                message: "Items added to bill.",
                items: items
            )
        }

        // 3. Try generic JSONSerialization dictionary inspection
        if let dict = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] {
            var extractedItems: [AgentParsedItem] = []

            for key in ["items", "products", "order", "item_list", "billedItems"] {
                if let rawList = dict[key] as? [[String: Any]] {
                    for itemDict in rawList {
                        if let itemData = try? JSONSerialization.data(withJSONObject: itemDict),
                           let parsedItem = try? JSONDecoder().decode(AgentParsedItem.self, from: itemData) {
                            extractedItems.append(parsedItem)
                        }
                    }
                    break
                }
            }

            // Or if root dictionary is a single item itself (has itemName, name, or item)
            if extractedItems.isEmpty && (dict["itemName"] != nil || dict["name"] != nil || dict["item"] != nil) {
                if let itemData = try? JSONSerialization.data(withJSONObject: dict),
                   let parsedItem = try? JSONDecoder().decode(AgentParsedItem.self, from: itemData) {
                    extractedItems.append(parsedItem)
                }
            }

            if !extractedItems.isEmpty {
                let status = (dict["status"] as? String) ?? "ready"
                let message = (dict["message"] as? String) ?? (dict["response"] as? String) ?? ""
                let thought = dict["thought"] as? String
                return AgentJsonPayload(
                    status: status,
                    message: message,
                    thought: thought,
                    items: extractedItems
                )
            }
        }

        return nil
    }

    /// Resilient fallback item extractor for edge cases where the LLM produces unstructured or natural language confirmations.
    private static func extractFallbackItems(from text: String, catalog: [Item]) -> [AgentParsedItem] {
        var items: [AgentParsedItem] = []
        let lower = text.lowercased()

        for item in catalog {
            let itemNameLower = item.name.lowercased()
            if lower.contains(itemNameLower) {
                let pattern = #"([0-9]+(?:\.[0-9]+)?)\s*(?:kg|kilo|gram|g|l|litre|liter|ml|pc|piece|dozen|pkt|packet)?\s*"# + NSRegularExpression.escapedPattern(for: itemNameLower)
                var qty: Double = 1.0
                let unitStr = item.unitType.shortLabel

                if let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]),
                   let match = regex.firstMatch(in: lower, options: [], range: NSRange(location: 0, length: lower.utf16.count)) {
                    if let numRange = Range(match.range(at: 1), in: lower),
                       let num = Double(lower[numRange]) {
                        qty = num
                    }
                }

                items.append(
                    AgentParsedItem(
                        itemId: item.id.uuidString,
                        itemName: item.name,
                        quantity: qty,
                        unit: unitStr,
                        unitPrice: item.pricePerUnit
                    )
                )
            }
        }

        return items
    }
}
